SELECT AVG(Age) AS Average_Age, MIN(Age) AS Minimum_Age, MAX(Age) AS Maximum_Age 
FROM singer 
WHERE Country = 'France';

SELECT AVG(Age) AS Average_Age, MIN(Age) AS Minimum_Age, MAX(Age) AS Maximum_Age 
FROM singer 
WHERE Country = 'France';

SELECT Country, COUNT(*) AS Number_of_Singers
FROM singer
GROUP BY Country;

SELECT T1.Name AS Stadium_Name, T1.Capacity FROM stadium AS T1 INNER JOIN (
    SELECT Stadium_ID, AVG(Average) AS Avg_Average FROM stadium GROUP BY Stadium_ID ORDER BY Avg_Average DESC LIMIT 1
) AS T2 ON T1.Stadium_ID = T2.Stadium_ID;

SELECT T1.Name AS Stadium_Name, T1.Capacity AS Stadium_Capacity 
FROM stadium AS T1 
WHERE T1.Average = (SELECT MAX(Average) FROM stadium);

SELECT T1.Name 
FROM singer AS T1 
WHERE T1.Age > (SELECT AVG(Age) FROM singer);

SELECT T1.Name FROM stadium AS T1 JOIN (
    SELECT Stadium_ID, AVG(Capacity) AS Avg_Capacity 
    FROM stadium 
    GROUP BY Stadium_ID
) AS T2 ON T1.Stadium_ID = T2.Stadium_ID WHERE T1.Capacity > T2.Avg_Capacity;

SELECT singer.Name 
FROM singer 
WHERE singer.Age > 25 AND singer.Is_male = 1;

SELECT COUNT(CASE WHEN Is_male = 'Male' THEN 1 ELSE NULL END) AS Male_Singers, 
       COUNT(CASE WHEN Is_male = 'Female' THEN 1 ELSE NULL END) AS Female_Singers 
FROM singer;

SELECT Year, COUNT(DISTINCT Singer_ID) AS Number_of_Singers_Participations
FROM concert
GROUP BY Year;

SELECT T1.Name FROM stadium AS T1 JOIN (
    SELECT Stadium_ID, AVG(Average) AS Avg_Avg_Capacity FROM stadium GROUP BY Stadium_ID
) AS T2 ON T1.Stadium_ID = T2.Stadium_ID WHERE T1.Capacity > T2.Avg_Avg_Capacity;

SELECT T1.Name FROM stadium AS T1 JOIN (
    SELECT Stadium_ID, AVG(Capacity) AS Avg_Capacity 
    FROM stadium 
    GROUP BY Stadium_ID
) AS T2 ON T1.Stadium_ID = T2.Stadium_ID WHERE T1.Capacity < T2.Avg_Capacity;

SELECT singer.Name FROM singer 
JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID 
JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID;

SELECT singer.Name 
FROM singer 
WHERE NOT EXISTS (
    SELECT 1 FROM singer_in_concert 
    WHERE singer.Singer_ID = singer_in_concert.Singer_ID
);

SELECT Stadium_ID, COUNT(DISTINCT concert_ID) AS Number_of_Distinct_Concerts_Held 
FROM stadium 
GROUP BY Stadium_ID;

SELECT DISTINCT T1.Name FROM stadium AS T1 JOIN (
    SELECT c.Stadium_ID FROM singer AS s INNER JOIN concert AS c ON s.Singer_ID = c.concert_ID GROUP BY c.Stadium_ID HAVING COUNT(DISTINCT T2.Country) > 1
) AS T2 ON T1.Stadium_ID = T2.Stadium_ID;
